import {showTexture} from './texture.js';
import {currentMesh,editMesh} from '../scene/mesh-edit.js';import {showMeshColour} from './mesh-colour.js';
import {fitMesh,constrainMeshPoint} from '../scene/contour.js';import {lineStyles,lineProfiles} from '../scene/strokes.js';
import {combineShapes,joinPaths} from '../scene/boolean.js';import {putKey,enableTrack,allTracks} from '../animation/evaluate.js';
import {find,locate,selectionRoots,isLocked,clone} from '../document/model.js';
import {evaluated,setProperty} from '../animation/evaluate.js';
import {world,worldBounds,localBounds,point,inverse,multiply,identity} from '../scene/matrix.js';
import {convertToPath,shapeNodes,splitSegment,editNode} from '../scene/shapes.js';
import {createMesh,refineMesh,subdivideMesh} from '../scene/mesh.js';
export function editorControls(a,n){
 const v=evaluated(n,a.time),path=['path','freehand'].includes(n.type),mesh=currentMesh(n,a.time),p=mesh?.points[Math.min(a.activeMesh||0,mesh.points.length-1)];
 return `<div class="prop-section"><div class="prop-title">Object selection</div><div class="editor-buttons"><button data-edit="direct" class="${a.tool==='direct'?'active':''}">Direct select</button>${n.type==='group'?'<button data-edit="contents">Select contents</button>':'<button data-edit="convert">Edit as path</button>'}<button data-edit="front">Bring forward</button><button data-edit="back">Send backward</button><button data-edit="flip-x">Flip horizontal</button><button data-edit="flip-y">Flip vertical</button></div></div>
 ${n.type==='rectangle'?`<div class="prop-section"><label>Corner radius<input type="number" data-geometry="radius" min="0" max="${Math.min(n.width,n.height)/2}" value="${n.radius||0}"></label></div>`:''}
 ${n.shapeKind&&n.shapeKind!=='line'?`<div class="prop-section"><div class="prop-title">${n.shapeKind==='star'?'Star':'Polygon'} shape</div><div class="prop-grid"><label>${n.shapeKind==='star'?'Points':'Sides'}<input type="number" data-geometry="sides" min="3" max="32" value="${n.sides||6}"></label>${n.shapeKind==='star'?`<label>Inner radius<input type="number" data-geometry="innerRatio" min=".05" max=".95" step=".05" value="${n.innerRatio||.45}"></label>`:''}</div></div>`:''}
 ${path?`<div class="prop-section"><div class="prop-title">Path points ${Number.isInteger(a.activeNode)?'· '+(a.activeNode+1):''}</div><div class="editor-buttons"><button data-edit="nodes" class="${a.nodeEdit?'active':''}">Edit points</button><button data-edit="split">Add midpoint</button><button data-edit="smooth">Smooth point</button><button data-edit="corner">Corner point</button><button data-edit="delete-point">Delete point</button></div><label>Selected point bevel radius (px)<input type="number" min="0" max="2048" data-node-prop="bevelRadius" value="${Number.isInteger(a.activeNode)?v.nodes[a.activeNode]?.bevelRadius||0:0}" ${!Number.isInteger(a.activeNode)?'disabled':''}></label><p class="subtle">Tap a square point to select it. Drag points or round curve handles. Add midpoint splits the next segment without changing the curve.</p></div>`:''}
 ${n.type!=='group'&&n.type!=='text'?`<div class="prop-section"><div class="prop-title">Mesh shading</div>${mesh?`<div class="mesh-summary">${mesh.rows} × ${mesh.cols} colour grid</div><div class="editor-buttons"><button data-edit="mesh" class="${a.tool==='mesh'?'active':''}">Edit mesh</button><button data-edit="mesh-bounds">Set mesh bounds</button><button data-edit="mesh-insert">Add mesh point</button><button data-edit="highlight">Add highlight</button></div><label>Point ${(a.activeMesh||0)+1} colour<input type="color" data-mesh-prop="color" value="${p.color}"></label><div class="prop-grid"><label>Point X<input type="number" data-mesh-prop="x" step="1" value="${Math.round(p.x*100)/100}"></label><label>Point Y<input type="number" data-mesh-prop="y" step="1" value="${Math.round(p.y*100)/100}"></label></div><div class="editor-buttons"><button data-edit="mesh-row">Add row</button><button data-edit="mesh-col">Add column</button><button data-edit="mesh-fit">Fit mesh to shape</button><button data-edit="mesh-reset">Reset mesh</button><button data-edit="mesh-remove">Remove mesh</button></div><p class="subtle">Use Mesh, tap a colour point, then choose its colour. Drag points to position the shading. Mesh colours are saved and exported with your shape.</p>`:'<button data-edit="mesh">Add colour mesh</button><p class="subtle">Shade your shape by giving each point its own colour.</p>'}</div>`:''}
 ${n.type!=='group'&&n.type!=='text'?lineControls(n):''}
 <div class="prop-section"><div class="prop-title">Align selection</div><div class="editor-buttons">${[['left','Left'],['center','Centre X'],['right','Right'],['top','Top'],['middle','Centre Y'],['bottom','Bottom']].map(([k,label])=>`<button data-edit="align-${k}">${label}</button>`).join('')}</div><p class="subtle">One shape aligns to the canvas. Multiple shapes align to their combined bounds.</p></div>`;
}
export function editorAction(a,action){
 const n=find(a.doc,a.selected[0]);if(!n||isLocked(a.doc,n.id))return;if(action==='texture')return showTexture(a);if(action.startsWith('combine-')||action==='join'){a.mutate('Combine paths',()=>{const result=action==='join'?joinPaths(a.doc,a.selected,a.time):combineShapes(a.doc,a.selected,action.slice(8),a.time);a.selected=[result.id];a.tool='direct';a.nodeEdit=true;a.activeNode=null;});return;}if(action==='previous-point'||action==='next-point'){const length=evaluated(n,a.time).nodes.length;a.activeNode=((a.activeNode??(action==='previous-point'?0:-1))+(action==='previous-point'?-1:1)+length)%length;a.nodeEdit=true;a.render();return;}if(['split','smooth','corner','delete-point'].includes(action)&&!Number.isInteger(a.activeNode))return a.toast('Tap a square path point first.');if(action==='mesh-placement-cancel'){a.meshPlacement=null;a.meshInsert=false;a.meshSplit=false;a.render();return;}if(action==='mesh-bounds'){if(['group','text','image'].includes(n.type))return a.toast('Choose an individual closed shape.');a.tool='mesh';a.nodeEdit=false;a.meshPlacement={id:n.id};a.meshInsert=false;a.meshSplit=false;a.render();a.toast('Tap one side or corner inside the shape, then the opposite side or corner.');return;}if(action==='mesh-insert'){if(!n.mesh)return a.toast('Add a colour mesh first.');a.tool='mesh';a.nodeEdit=false;a.meshInsert=!a.meshInsert;a.meshPlacement=null;a.meshSplit=false;a.render();return;}if(action==='mesh-colour')return showMeshColour(a);if(action==='mesh-tap'){a.meshPlacement=null;a.meshInsert=false;a.meshSplit=!a.meshSplit;a.render();return;}
 if(action==='contents'){a.selected=n.children.filter(c=>!isLocked(a.doc,c.id)).map(c=>c.id);a.multi=true;return a.render();}
 if(action==='direct'||action==='nodes'||action==='convert'){a.meshPlacement=null;a.meshInsert=false;a.meshSplit=false;a.mutate('Edit shape points',()=>{if(n.type!=='group'&&n.type!=='text')convertToPath(n);});a.tool='direct';a.nodeEdit=true;a.activeNode=null;if(n.type==='text')document.querySelector('.inspector').classList.add('open');return a.render();}
 if(action==='mesh'){a.meshPlacement=null;a.meshInsert=false;a.meshSplit=false;if(['group','text','image'].includes(n.type))return a.toast('Choose an individual closed shape for mesh shading.');a.mutate('Add colour mesh',()=>{if(['path','freehand'].includes(n.type)&&!n.closed&&!n.nodes.some(p=>p.close))throw Error('Close the path before adding mesh shading.');if(n.fill==='none')setProperty(n,'fill',a.drawColor,a.time);n.mesh||=fitMesh(n,a.time);});if(!n.mesh)return;a.tool='mesh';a.meshInsert=true;a.nodeEdit=false;a.activeMesh=Math.floor(n.mesh.points.length/2);return a.render();}
 a.mutate('Edit '+action,()=>{
  if(action==='split'){a.activeNode=splitSegment(n,a.activeNode??0,a.time);delete n.shapeKind;}
  else if(['smooth','corner','delete-point'].includes(action)){editNode(n,a.activeNode??0,action==='delete-point'?'delete':action,a.time);delete n.shapeKind;if(action==='delete-point')a.activeNode=null;}
  else if(action==='mesh-key')enableTrack(n,'mesh',a.time,a.ease);else if(action==='shape-key')enableTrack(n,'nodes',a.time,a.ease);else if(action==='toggle-close'){const closed=n.closed||n.nodes.some(p=>p.close);n.closed=!closed;if(closed)n.nodes.forEach(p=>delete p.close);}else if(action==='reverse'){const groups=[];let part=[];for(const p of evaluated(n,a.time).nodes){if(p.move&&part.length){groups.push(part);part=[];}part.push(p);if(p.close){groups.push(part);part=[];}}if(part.length)groups.push(part);const nodes=groups.flatMap(part=>{const closed=part.at(-1).close;return [...part].reverse().map((p,i)=>{const q={...p,in:p.out,out:p.in};delete q.move;delete q.close;if(i===0&&groups.length>1)q.move=true;if(i===part.length-1&&closed)q.close=true;return q;});});setProperty(n,'nodes',nodes,a.time);delete n.shapeKind;}else if(action==='mesh-split'){const m=currentMesh(n,a.time),index=Math.min(a.activeMesh||0,m.points.length-1),row=Math.min(m.rows-2,Math.floor(index/m.cols)),col=Math.min(m.cols-2,index%m.cols);editMesh(n,a.time,m=>subdivideMesh(m,row,col),true);a.activeMesh=(row+1)*currentMesh(n,a.time).cols+col+1;}else if(action==='mesh-remove'){delete n.mesh;for(const tracks of allTracks(n))delete tracks.mesh;for(const b of n.blocks||[])b.props=b.props.filter(p=>p!=='mesh');for(const c of n.blockCuts||[])delete c.values.mesh;a.meshPlacement=null;a.meshInsert=false;}
  else if(action==='texture-remove')delete n.texture;
  else if(action==='mesh-fit')editMesh(n,a.time,m=>{delete m.manualBounds;return fitMesh(n,a.time,m);});
  else if(action==='mesh-reset')editMesh(n,a.time,m=>{const reset=fitMesh(n,a.time,m);reset.points.forEach(p=>p.color=evaluated(n,a.time).fill);return reset;});
  else if(action==='mesh-row'||action==='mesh-col'){editMesh(n,a.time,m=>refineMesh(m,action==='mesh-row'?'rows':'cols'),true);a.activeMesh=0;}
  else if(action==='highlight'){const m=currentMesh(n,a.time),index=Math.floor(m.rows/2)*m.cols+Math.floor(m.cols/2);editMesh(n,a.time,m=>{m.points[index].color='#ffffff';return m;});a.activeMesh=index;}
  else if(action==='front'||action==='back'){const roots=selectionRoots(a.doc,a.selected);for(const node of action==='front'?[...roots].reverse():roots){if(isLocked(a.doc,node.id))continue;const l=locate(a.doc,node.id),to=Math.max(0,Math.min(l.list.length-1,l.index+(action==='front'?1:-1)));[l.list[l.index],l.list[to]]=[l.list[to],l.list[l.index]];}}
  else if(action.startsWith('flip-')){for(const node of selectionRoots(a.doc,a.selected)){if(isLocked(a.doc,node.id))continue;const k=action==='flip-x'?'scaleX':'scaleY',b=localBounds(node,a.time),v=evaluated(node,a.time),center={x:b.x+b.width/2,y:b.y+b.height/2},old=point(world(a.doc,node.id,a.time),center);setProperty(node,k,-v[k],a.time);moveWorld(a,node,old.x-point(world(a.doc,node.id,a.time),center).x,old.y-point(world(a.doc,node.id,a.time),center).y);}}
  else if(action.startsWith('align-')){const roots=selectionRoots(a.doc,a.selected).filter(n=>!isLocked(a.doc,n.id)),bs=roots.map(n=>worldBounds(a.doc,n,a.time)),target=roots.length===1?{x:0,y:0,width:a.doc.width,height:a.doc.height}:{x:Math.min(...bs.map(b=>b.x)),y:Math.min(...bs.map(b=>b.y)),width:Math.max(...bs.map(b=>b.x+b.width))-Math.min(...bs.map(b=>b.x)),height:Math.max(...bs.map(b=>b.y+b.height))-Math.min(...bs.map(b=>b.y))},mode=action.slice(6);roots.forEach((n,i)=>{const b=bs[i],dx=mode==='left'?target.x-b.x:mode==='center'?target.x+target.width/2-b.x-b.width/2:mode==='right'?target.x+target.width-b.x-b.width:0,dy=mode==='top'?target.y-b.y:mode==='middle'?target.y+target.height/2-b.y-b.height/2:mode==='bottom'?target.y+target.height-b.y-b.height:0;moveWorld(a,n,dx,dy);});}
 });
}
function moveWorld(a,n,dx,dy){const l=locate(a.doc,n.id),m=inverse(multiply(l.parent?world(a.doc,l.parent.id,a.time):identity(),n.prefix||identity())),d=point(m,{x:dx,y:dy}),zero=point(m,{x:0,y:0}),v=evaluated(n,a.time);setProperty(n,'x',v.x+d.x-zero.x,a.time);setProperty(n,'y',v.y+d.y-zero.y,a.time);}
export function editorInput(properties,e){const a=properties.app,n=find(a.doc,a.selected[0]);if(!n||isLocked(a.doc,n.id))return false;const meshProp=e.target.dataset.meshProp,geometry=e.target.dataset.geometry,nodeProp=e.target.dataset.nodeProp;if(!meshProp&&!geometry&&!nodeProp)return false;if(nodeProp&&!Number.isInteger(a.activeNode))return true;const value=e.target.type==='number'?Number(e.target.value):e.target.value;if(e.target.value===''||typeof value==='number'&&!Number.isFinite(value))return true;a.pause();a.history.begin();if(meshProp&&n.mesh){const m=clone(currentMesh(n,a.time)),p=m.points[Math.min(a.activeMesh||0,m.points.length-1)],b=m.bounds;if(meshProp==='color')a.rememberColor(value);if(meshProp==='color')p.color=value;else Object.assign(p,constrainMeshPoint(n,a.time,{x:p.x,y:p.y,[meshProp]:value},m));setProperty(n,'mesh',m,a.time);}if(nodeProp){const nodes=clone(evaluated(n,a.time).nodes),p=nodes[a.activeNode];if(!p)return true;p[nodeProp]=nodeProp==='bevelStyle'?(value==='bevel'?'bevel':'round'):Math.max(0,Math.min(2048,value));setProperty(n,'nodes',nodes,a.time);}if(geometry){n[geometry]=geometry==='sides'?Math.max(3,Math.min(32,Math.round(value))):geometry==='innerRatio'?Math.max(.05,Math.min(.95,value)):Math.max(0,Math.min(n.width/2,n.height/2,value));if(n.shapeKind)n.nodes=shapeNodes(n.shapeKind,n.width,n.height,n.sides,n.innerRatio);}properties.pending=true;a.renderStage();clearTimeout(properties.inputTimer);properties.inputTimer=setTimeout(()=>properties.flush(),500);return true;}

export function lineControls(n){const select=(key,label,values)=>'<label>'+label+'<select data-prop="'+key+'">'+values.map(([value,title])=>'<option value="'+value+'" '+((n[key]||{lineStyle:'solid',strokeProfile:'uniform',lineCap:'round',lineJoin:'round'}[key])===value?'selected':'')+'>'+title+'</option>').join('')+'</select></label>';return '<div class="prop-section"><div class="prop-title">Line style & width profile</div><div class="prop-grid">'+select('lineStyle','Line style',lineStyles.map(x=>[x,x[0].toUpperCase()+x.slice(1)]))+select('strokeProfile','Width profile',[['uniform','Uniform'],['taper-both','Taper both ends'],['taper-start','Thin to thick'],['taper-end','Thick to thin'],['brush','Brush bulge']])+select('lineCap','Line ends',[['round','Round'],['butt','Flat'],['square','Square']])+select('lineJoin','Corners',[['round','Round'],['miter','Sharp'],['bevel','Bevel']])+'</div><p class="subtle">Set Stroke width above zero. Profiles follow the path and export with your animation.</p></div>';}
